const fail = (message) => Promise.reject(new Error(message));

async function run() {
  try {
    await fail("first");
    console.log("never");
  } catch (error) {
    console.log("caught " + error.message);
  } finally {
    console.log("cleanup");
  }
  return "end";
}

run().then((value) => console.log(value));
